// Purpose: ROW-002 (REQ-001) — on the checker page, in every browser of the harness, each flagged word
// is highlighted at its own position in the text, including when the same word stands several times
// and only one occurrence is misspelled; plus a control with a single misspelling written once.
// Provenance: generated by tests/invariants/spanish-dictionary.ts (accentPopulation, over dictionary-es
// 4.0.0 pinned by SHA-256) with a fresh seed per run; expected positions are the test's own record of
// where it placed each word, never the product's answer.
//
// Test argument
// ROW-002 promise: each flagged word is highlighted at its own place in the text (REQ-001 AMENDED
//   arm 3: "a flagged word is highlighted anywhere but at its own position" fails it; A-005: each
//   misspelled word highlighted in the text), including when the same word occurs several times and
//   only one occurrence is misspelled (the row's own case); positions as D-020 defines them.
// ROW-002 wrong product: a page that places each highlight by searching the text for the flagged
//   word — the first match of "gestion" falls inside the correct "gestiones" written before it — or
//   by an accent-insensitive search, whose first match is the correct "gestión" written before the
//   misspelled one; either highlights a correct word and leaves the misspelling bare.
// ROW-002 given: a fresh dictionary word w ending in -ión (from the population) written three times
//   correctly, its plural d = stripped+"es" (correct, containing the misspelling as its prefix)
//   written before the one misspelled occurrence s, and a second fresh pair u/t (u twice correct, t
//   once misspelled after the first u), between random filler words; when: the text is entered in the
//   box and Revisar ortografía is pressed; then: the page shows exactly two highlights, one on s and
//   one on t, each at the offsets where the test placed it, each visible and drawn apart from the
//   surrounding text — and before the press there was none.
// ROW-002 controls: a text with a single misspelling written once and no repeat or decoy is
//   highlighted at its place — the page, the check and the highlight reading all work, and a
//   search-by-word page passes it, so only the target separates placing from searching.
// ROW-002 technique: decoys and repeats built from fresh population words (positions and words new
//   every run), compared as a whole list (no extra highlight, none missing), on the engine door,
//   because a highlight is paint; per browser in the harness's four projects (RULE-014, REQ-042).
// cases: ROW-002 target=ROW-002-each-flagged-word-highlighted-at-its-own-position-among-repeats-and-decoys control=ROW-002-control-a-single-misspelling-is-highlighted-at-its-place

import { expect, test } from '@playwright/test';
import {
  accentPopulation,
  asActor,
  compose,
  enterOffer,
  fillerWords,
  freshRandom,
  isDictionaryWord,
  openChecker,
  pressCheck,
  readHighlights,
  stripAcuteAccents,
  type Highlight,
  type Placed,
  type Rng,
} from './harness';

const HIGHLIGHT_WAIT_MS = 15_000;

function withFillers(rng: Rng, anchors: string[]): string[] {
  const fillers = fillerWords();
  const tokens: string[] = [];
  for (const anchor of anchors) {
    for (let i = rng.int(2); i >= 0; i--) tokens.push(rng.pick(fillers));
    tokens.push(anchor);
  }
  tokens.push(rng.pick(fillers));
  return tokens;
}

const shown = (p: Placed): Highlight => ({ word: p.word, start: p.start, end: p.end, visible: true, marked: true });

test('ROW-002-each-flagged-word-highlighted-at-its-own-position-among-repeats-and-decoys', async ({ page }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const population = accentPopulation();
  const withPlural = population.filter((p) => p.word.endsWith('ión') && isDictionaryWord(p.stripped + 'es'));
  expect(withPlural.length, 'ROW-002 setup: the population offers -ión words with a correct plural').toBeGreaterThan(100);

  const a = rng.pick(withPlural);
  let b = rng.pick(population);
  while (b.word === a.word || b.stripped.includes(a.stripped) || a.stripped.includes(b.stripped)) b = rng.pick(population);
  const w = a.word; // correct, written three times
  const s = a.stripped; // misspelled, written once
  const d = a.stripped + 'es'; // correct plural, contains s, written before s
  const u = b.word; // correct, written twice
  const t = b.stripped; // misspelled, written once, after the first u

  const { text, placed } = compose(withFillers(rng, [w, d, w, s, u, t, w, u]));
  const expected = placed.filter((p) => p.word === s || p.word === t).map(shown);
  expect(expected.length, 'ROW-002 setup: each misspelling stands once in the text').toBe(2);

  await openChecker(page);
  await enterOffer(page, text);
  expect(await readHighlights(page, text), 'ROW-002: nothing is highlighted before Revisar ortografía is pressed').toEqual([]);

  const { status } = await pressCheck(page);
  expect(status, 'ROW-002: the page\'s check request is answered').toBe(200);
  await expect
    .poll(() => readHighlights(page, text), {
      message: `ROW-002: in ${JSON.stringify(text)} exactly "${s}" and "${t}" are highlighted, each where it stands — not the correct "${w}", "${d}" or "${u}" (seed ${rng.seed})`,
      timeout: HIGHLIGHT_WAIT_MS,
    })
    .toEqual(expected);
});

test('ROW-002-control-a-single-misspelling-is-highlighted-at-its-place', async ({ page }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const fillers = fillerWords().map(stripAcuteAccents);
  // no filler may hold the misspelling or its accented form: this text has no decoy and no repeat
  const one = rng.pick(accentPopulation().filter((p) => !fillers.some((f) => f.includes(p.stripped))));
  const { text, placed } = compose(withFillers(rng, [one.stripped]));
  const expected = placed.filter((p) => p.word === one.stripped).map(shown);
  expect(expected.length, 'ROW-002 setup: the misspelling stands once in the text').toBe(1);

  await openChecker(page);
  await enterOffer(page, text);
  expect(await readHighlights(page, text), 'ROW-002 control: nothing is highlighted before Revisar ortografía is pressed').toEqual([]);

  const { status } = await pressCheck(page);
  expect(status, 'ROW-002 control: the page\'s check request is answered').toBe(200);
  await expect
    .poll(() => readHighlights(page, text), {
      message: `ROW-002 control: "${one.stripped}" is highlighted where it stands in ${JSON.stringify(text)} (seed ${rng.seed})`,
      timeout: HIGHLIGHT_WAIT_MS,
    })
    .toEqual(expected);
});
